// รับ catalog array จาก admin.html
const body = $input.first().json.body || $input.first().json;
const catalog = body.catalog || [];

const esc = (s) => String(s == null ? '' : s).replace(/'/g, "''");
const boolVal = (v) => (v === true || v === 'true' || v === 1) ? 'true' : 'false';

let sql;

if (catalog.length === 0) {
  sql = 'SELECT 1;';
} else {
  const cols = [
    'bike_type','submodel_name','model_name','variant_name','marketing_name',
    'engine_cc','transmission','is_active','sort_order','note','badge','colors',
    'auto_rate','auto_rate_unit','auto_down_pcts','auto_rate2','auto_rate2_min_down'
  ].join(',');

  const values = catalog.map(c =>
    `('${esc(c.bike_type)}','${esc(c.submodel_name)}','${esc(c.model_name)}','${esc(c.variant_name)}','${esc(c.marketing_name)}',${parseInt(c.engine_cc)||0},'${esc(c.transmission||'Automatic')}',${boolVal(c.is_active)},${parseInt(c.sort_order)||0},'${esc(c.note)}','${esc(c.badge||'')}','${esc(c.colors)}',${parseFloat(c.auto_rate)||0},'${esc(c.auto_rate_unit||'month')}','${esc(c.auto_down_pcts)}',${parseFloat(c.auto_rate2)||0},${parseInt(c.auto_rate2_min_down)||0})`
  ).join(',\n');

  sql = `DELETE FROM bike_catalog;\nINSERT INTO bike_catalog (${cols})\nVALUES\n${values};`;
}

return [{ json: { sql, count: catalog.length } }];
